53	  inline bool update (uintE s, uintE d) {
54	    long toWrite = Visited[d] | Visited[s];
55	    if(Visited[d] != toWrite) {
56	      NextVisited[d] |= toWrite;
57	      if(radii[d] != round) { radii[d] = round; return 1; }
