63	    if(Visited[d] != toWrite) {
64	      writeOr(&NextVisited[d],toWrite);
65	      intE oldRadii = radii[d];
66	      //only one of the concurrent updaters wins the CAS and returns d
67	      if(oldRadii != round) return CAS(&radii[d],oldRadii,round);
68	    }
69	    return 0;
